import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Diagonale e lato del quadrato sono incommensurabili","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fn/fnca.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fn/fnca.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fn/fnca.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="diagonale-e-lato-del-quadrato-sono-incommensurabili" tabindex="-1">Diagonale e lato del quadrato sono incommensurabili <a class="header-anchor" href="#diagonale-e-lato-del-quadrato-sono-incommensurabili" aria-label="Permalink to “Diagonale e lato del quadrato sono incommensurabili”">​</a></h1><p>Per parlare di questo teorema dobbiamo parlare di Pitagora e della setta dei pitagorici. I pitagorici erano una specie di multinazionale del quinto secolo avanti Cristo, con sede centrale a Crotone, ma con le mani in pasta nei governi delle varie città della Magna Grecia, dove riuscivano a indirizzare le politiche dei vari tiranni utilizzando la loro magia-religione basata sulla numerologia.</p><p>Erano persone piuttosto strane per l&#39;epoca, vegetariani perché credevano alla trasmigrazione delle anime, dormivano meno di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>4</mn></mrow><annotation encoding="application/x-tex">4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">4</span></span></span></span> ore per notte e somigliavano più a dei monaci che a dei matematici.</p><p>Pitagora ed i pitagorici erano guidati dalla fede che il numero fosse il principio di tutte le cose, cioè la Divinità stessa.</p><p>Ottennero vari successi, sembra che lo stesso Pitagora scoprisse la relazione fra la musica e le frazioni e questo lo rinforzò nella sua fede.</p><p>Quando questo teorema fu scoperto, ebbe l&#39;effetto di un terremoto sui pitagorici (non si sa se Pitagora fosse ancora vivo): il numero, che doveva essere la divinità, non riusciva nemmeno a misurare il rapporto fra due segmenti! Era come scoprire che il Dio fino allora adorato era il diavolo!</p><p>Si cercò di tenere segreto il teorema anche fra gli adepti, ma ci fu chi parlò, e sebbene pagasse la sua colpa con il suo assassinio, ormai il teorema era nozione comune e la fede pitagorica crollò.</p><p>Se una civiltà quale la pitagorica si basa su una fede e questa fede crolla, anche la civiltà è destinata a sparire: vi furono rivolte ed i pitagorici furono perseguitati ed i loro centri bruciati, la civiltà pitagorica passò il testimone a Platone ed Aristotele.</p><blockquote><p><strong>Commento</strong> alla Pierino: &quot;È tutto questo per un teorema!&quot;</p></blockquote>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};